from __future__ import annotations
import base64, io, tarfile
from pathlib import Path

ARCHIVE = """"""
root = Path(__file__).resolve().parents[1]
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(ARCHIVE)), mode="r:gz") as tf:
    tf.extractall(root)
print(f"Bootstrapped implementation files into {root}")
